import typer

from . import __version__

app = typer.Typer(help="A Claude-Code-style terminal over Cortex Code for the team's knowledge system, rebuilt from the canon.", no_args_is_help=True)


@app.command()
def version() -> None:
    """Print the version."""
    typer.echo(__version__)


@app.command()
def hello(name: str = "world") -> None:
    """Say hello. Replace with the first real command."""
    typer.echo(f"hello, {name}")

