# Read the canon's index and standards

Find the canon, load its `index.json`, and read a standard's text. Written after a rebuild that
could reach the canon only through MCP tools had to guess the index's layout.

## The index

`index.json` has three lists. Every entry has `id`, `version` (int), `title`, `status`
(`accepted` or `proposed`) and `owner`.

- `standards`: also `applies_to` (tag patterns, `*` for all), `path` (the file, relative to the
  canon), `kind` (`standard`, or `gotcha` for a lesson). The file starts with `---` front matter.
- `scaffolds`: also `path` (menu path, e.g. `["python", "cli"]`), `tags`, `defaults`, `dir`,
  `files` and `hash`. Render one with [[block-scaffold-render]].
- `blocks`: also `module`, `requires`, `test_requires`, `tags`, `dir`, `tests` and `hash`.

## API

`canon_root(env=None) -> Path`: `$DS_CANON`, else `~/Developer/canon`.
`Canon.load(root) -> Canon`, which never raises: a missing or broken index gives empty lists and
a line in `.problems`. `.standards`, `.scaffolds`, `.blocks` (lists of dicts, as in the index),
`.counts()` (`{"standards": n, "scaffolds": n, "blocks": n}`), `.accepted(kind)`,
`.find(kind, id)`, `.read_standard(id) -> str` (body without front matter; raises `KeyError` for
an unknown id and `ValueError` for a path outside the canon), `.versions()` (`{id: version}`
across all three), `.applicable(tags)` (standards whose `applies_to` matches), and `.refresh()`
(reloads when `index.json` changed on disk).

## Why it is shaped this way

[[gotcha-validation]] (never raise on bad input in a check), [[gotcha-confined-writes]] (paths
from data stay inside their root).


--- src/<package>/canonreader.py
"""Find the canon, load its index.json, read a standard. Never raises on a bad index."""
from __future__ import annotations

import fnmatch
import json
import os
from collections.abc import Mapping
from pathlib import Path
from typing import Any

KINDS = ("standards", "scaffolds", "blocks")


def canon_root(env: Mapping[str, str] | None = None) -> Path:
    env = os.environ if env is None else env
    return Path(env["DS_CANON"]).expanduser() if env.get("DS_CANON") else Path.home() / "Developer" / "canon"


def strip_front_matter(text: str) -> str:
    if text.startswith("---\n"):
        _, sep, body = text[4:].partition("\n---\n")
        if sep:
            return body.lstrip("\n")
    return text


class Canon:
    def __init__(self, root: Path, data: dict[str, Any], problems: list[str], stamp: int | None):
        self.root, self.problems, self._stamp = Path(root), problems, stamp
        self.standards: list[dict] = data.get("standards", [])
        self.scaffolds: list[dict] = data.get("scaffolds", [])
        self.blocks: list[dict] = data.get("blocks", [])

    @classmethod
    def load(cls, root: Path | None = None) -> Canon:
        root = Path(root) if root is not None else canon_root()
        path = root / "index.json"
        try:
            stamp = path.stat().st_mtime_ns
            data = json.loads(path.read_text())
        except FileNotFoundError:
            return cls(root, {}, [f"no index.json in {root}"], None)
        except (OSError, ValueError) as e:
            return cls(root, {}, [f"{path}: {e}"], None)
        if not isinstance(data, dict):
            return cls(root, {}, [f"{path}: not a JSON object"], stamp)
        problems, clean = [], {}
        for kind in KINDS:
            rows = data.get(kind, [])
            if not isinstance(rows, list):
                problems.append(f"{kind}: not a list")
                rows = []
            good = [r for r in rows if isinstance(r, dict) and isinstance(r.get("id"), str)]
            if len(good) != len(rows):
                problems.append(f"{kind}: {len(rows) - len(good)} entries without an id skipped")
            clean[kind] = good
        return cls(root, clean, problems, stamp)

    def refresh(self) -> Canon:
        """This canon, or a fresh load if index.json changed since."""
        try:
            stamp = (self.root / "index.json").stat().st_mtime_ns
        except OSError:
            stamp = None
        return self if stamp == self._stamp else Canon.load(self.root)

    def counts(self) -> dict[str, int]:
        return {kind: len(getattr(self, kind)) for kind in KINDS}

    def accepted(self, kind: str) -> list[dict]:
        return [r for r in getattr(self, kind) if r.get("status") == "accepted"]

    def find(self, kind: str, rid: str) -> dict | None:
        return next((r for r in getattr(self, kind) if r["id"] == rid), None)

    def versions(self) -> dict[str, int]:
        out = {}
        for kind in KINDS:
            for r in getattr(self, kind):
                try:
                    out[r["id"]] = int(r.get("version", 0))
                except (TypeError, ValueError):
                    continue
        return out

    def applicable(self, tags: list[str]) -> list[dict]:
        def applies(s: dict) -> bool:
            return any(p == "*" or any(fnmatch.fnmatchcase(t, p) for t in tags) for p in s.get("applies_to", []))
        return [s for s in self.standards if applies(s)]

    def read_standard(self, sid: str) -> str:
        s = self.find("standards", sid)
        if s is None:
            raise KeyError(f"no standard {sid!r} in the canon")
        root = self.root.resolve()
        path = (root / str(s.get("path", ""))).resolve()
        if not path.is_relative_to(root) or path == root:
            raise ValueError(f"standard {sid!r}: path {s.get('path')!r} is outside the canon")
        return strip_front_matter(path.read_text())


--- tests/test_canonreader.py
import json

import pytest

from <package>.canonreader import Canon, canon_root, strip_front_matter


def make(root, data):
    root.mkdir(parents=True, exist_ok=True)
    (root / "index.json").write_text(json.dumps(data))
    return Canon.load(root)


def sample(root):
    (root / "gotchas").mkdir(parents=True)
    (root / "testing.md").write_text("---\nid: testing\nversion: 2\n---\n\n# Testing\n\nBody.\n")
    (root / "gotchas" / "g.md").write_text("---\nid: g\n---\n# G\n")
    return make(root, {
        "standards": [
            {"id": "testing", "version": 2, "title": "Testing", "status": "accepted", "owner": "o",
             "applies_to": ["*"], "path": "testing.md", "kind": "standard"},
            {"id": "g", "version": 1, "title": "G", "status": "proposed", "owner": "o",
             "applies_to": ["cortex"], "path": "gotchas/g.md", "kind": "gotcha"},
            {"id": "evil", "version": 1, "title": "E", "status": "accepted", "owner": "o",
             "applies_to": [], "path": "../outside.md"}],
        "scaffolds": [{"id": "python-cli", "version": 2, "status": "accepted", "title": "CLI"}],
        "blocks": [{"id": "block-a", "version": 3, "status": "accepted", "title": "A"},
                   {"id": "block-b", "version": 1, "status": "proposed", "title": "B"}]})


def test_root_from_env_else_home(tmp_path):
    assert canon_root({"DS_CANON": str(tmp_path)}) == tmp_path
    assert canon_root({}).parts[-2:] == ("Developer", "canon")


def test_counts_accepted_find_versions(tmp_path):
    c = sample(tmp_path / "canon")
    assert c.problems == []
    assert c.counts() == {"standards": 3, "scaffolds": 1, "blocks": 2}
    assert [b["id"] for b in c.accepted("blocks")] == ["block-a"]
    assert c.find("scaffolds", "python-cli")["version"] == 2
    assert c.versions()["block-a"] == 3 and c.versions()["testing"] == 2


def test_read_standard_strips_front_matter_and_stays_inside(tmp_path):
    c = sample(tmp_path / "canon")
    assert c.read_standard("testing").startswith("# Testing")
    with pytest.raises(KeyError):
        c.read_standard("nope")
    (tmp_path / "outside.md").write_text("secret")
    with pytest.raises(ValueError):
        c.read_standard("evil")


def test_applicable_matches_tag_patterns(tmp_path):
    c = sample(tmp_path / "canon")
    assert {s["id"] for s in c.applicable(["python"])} == {"testing"}
    assert {s["id"] for s in c.applicable(["cortex"])} == {"testing", "g"}


@pytest.mark.parametrize("content", ["not json", "[]", '{"standards": 5}', '{"blocks": [{"no": "id"}]}'])
def test_a_broken_index_never_raises(tmp_path, content):
    (tmp_path / "index.json").write_text(content)
    c = Canon.load(tmp_path)
    assert c.problems and c.counts()["standards"] == 0


def test_missing_index(tmp_path):
    c = Canon.load(tmp_path / "nowhere")
    assert c.counts() == {"standards": 0, "scaffolds": 0, "blocks": 0} and "no index.json" in c.problems[0]


def test_refresh_reloads_only_on_change(tmp_path):
    c = sample(tmp_path / "canon")
    assert c.refresh() is c
    data = json.loads((c.root / "index.json").read_text())
    data["blocks"].append({"id": "block-c", "version": 1, "status": "accepted"})
    import os
    (c.root / "index.json").write_text(json.dumps(data))
    os.utime(c.root / "index.json", ns=(c._stamp + 10**9, c._stamp + 10**9))
    assert c.refresh().counts()["blocks"] == 3


def test_strip_front_matter_leaves_plain_text():
    assert strip_front_matter("# Hi\n") == "# Hi\n"

