"""What a repository's .ds/manifest.toml records, compared with the canon. Never raises on a bad
manifest: every malformed value becomes a problem line. [[gotcha-validation]]"""
from __future__ import annotations

import tomllib
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

from .canonreader import Canon

STATUSES = ("adopted", "declined", "pending")


@dataclass
class Entry:
    id: str
    kind: str                       # "standard" or "block"
    status: str
    version: int
    canon: int | None               # the canon's current version, None when the canon lacks it
    reason: str = ""


@dataclass
class ManifestStatus:
    path: Path | None
    adopted: list[Entry] = field(default_factory=list)
    declined: list[Entry] = field(default_factory=list)
    pending: list[Entry] = field(default_factory=list)
    newer: list[Entry] = field(default_factory=list)
    unrecorded: list[str] = field(default_factory=list)
    problems: list[str] = field(default_factory=list)


def find_manifest(start: Path) -> Path | None:
    start = Path(start).resolve()
    for d in (start, *start.parents):
        p = d / ".ds" / "manifest.toml"
        if p.is_file():
            return p
    return None


def _version(v: Any) -> int | None:
    return v if isinstance(v, int) and not isinstance(v, bool) and v >= 1 else None


def read_status(start: Path, canon: Canon) -> ManifestStatus:
    path = find_manifest(start)
    out = ManifestStatus(path)
    if path is None:
        out.problems.append(f"no .ds/manifest.toml in {Path(start).resolve()} or above it")
        return out
    try:
        data = tomllib.loads(path.read_text())
    except (OSError, UnicodeDecodeError, tomllib.TOMLDecodeError) as e:
        out.problems.append(f"{path}: {e}")
        return out
    versions = canon.versions()
    repo = data.get("repo")
    tags = repo.get("tags") if isinstance(repo, dict) else None
    if not isinstance(tags, list) or not all(isinstance(t, str) for t in tags):
        out.problems.append("[repo] tags: not a list of strings")
        tags = []
    for kind, table in (("standard", "standards"), ("block", "blocks")):
        rows = data.get(table, {})
        if not isinstance(rows, dict):
            out.problems.append(f"[{table}]: not a table")
            continue
        for rid, row in rows.items():
            entry = _entry(rid, kind, row, versions, out.problems)
            if entry is None:
                continue
            {"adopted": out.adopted, "declined": out.declined, "pending": out.pending}[entry.status].append(entry)
            if entry.canon is not None and entry.canon > entry.version:
                out.newer.append(entry)
        if kind == "standard":
            out.unrecorded = sorted(s["id"] for s in canon.applicable(tags) if s["id"] not in rows)
    return out


def _entry(rid: str, kind: str, row: Any, versions: dict[str, int], problems: list[str]) -> Entry | None:
    if not isinstance(row, dict):
        problems.append(f"{rid}: not a table")
        return None
    status = row.get("status", "adopted" if kind == "block" else None)
    if status not in STATUSES:
        problems.append(f"{rid}: status {status!r} is not one of {', '.join(STATUSES)}")
        return None
    version = _version(row.get("version"))
    if version is None:
        problems.append(f"{rid}: version {row.get('version')!r} is not a positive integer")
        return None
    canon = versions.get(rid)
    if versions and canon is None:
        problems.append(f"{rid}: not in the canon")
    elif canon is not None and version > canon:
        problems.append(f"{rid}: v{version} is a version the canon never had (current v{canon})")
    reason = row.get("reason", "")
    if status == "declined" and (not isinstance(reason, str) or not reason.strip()):
        problems.append(f"{rid}: declined without a reason")
        reason = ""
    return Entry(rid, kind, status, version, canon, reason if isinstance(reason, str) else "")

