    return (f"# Interview\n\n- **name**: {draft.name}\n- **purpose**: {draft.purpose}\n"
            f"- **scaffold**: {s['id']} v{s.get('version')}\n- **owner**: {draft.owner}\n")


def create_project(cwd: Path, canon: Canon, draft: Draft) -> Path:
