"""The knowledge base as Cortex tools: list and read standards, list scaffolds, and the review's
verdict. All of them only read or report, so none asks for approval. [[gotcha-approvals]]"""
from __future__ import annotations

from collections.abc import Callable
from dataclasses import dataclass, field
from typing import Any

from cortex_agent_sdk.cortexcode import tool

from .canonreader import Canon
from .cortex_session import error_result, text_result

SERVER = "kb"
PREFIX = f"mcp__{SERVER}__"
READ_ONLY = frozenset({"list_standards", "read_standard", "list_scaffolds", "review_verdict"})

TAGS_SCHEMA = {"type": "object", "properties": {"tags": {
    "type": "string", "description": "Comma-separated repo tags, e.g. 'python,cli'. Empty lists every standard."}}}
ID_SCHEMA = {"type": "object", "properties": {"id": {"type": "string"}}, "required": ["id"]}
NO_ARGS = {"type": "object", "properties": {}}
VERDICT_SCHEMA = {"type": "object", "properties": {
    "ok": {"type": "boolean", "description": "true only when you have no concerns"},
    "concerns": {"type": "array", "items": {"type": "string"},
                 "description": "One sentence each, saying what to change. Empty when ok."}},
    "required": ["ok", "concerns"]}


@dataclass
class Verdicts:
    """What review_verdict reported. The review gates /new on this data, never on prose.
    [[gotcha-agent-trust]]"""
    calls: list[tuple[bool, list[str]]] = field(default_factory=list)

    def clear(self) -> None:
        self.calls.clear()

    def approved(self) -> bool:
        return bool(self.calls) and all(ok and not concerns for ok, concerns in self.calls)

    def concerns(self) -> list[str]:
        out = [c for _, concerns in self.calls for c in concerns]
        if not out and any(not ok for ok, _ in self.calls):
            out.append("The review did not approve the draft but named no concern.")
        return out


def standard_line(s: dict[str, Any]) -> str:
    applies = ", ".join(str(t) for t in s.get("applies_to", []))
    return f"{s['id']} v{s.get('version', '?')} ({s.get('kind', 'standard')}) [{applies}] {s.get('title', '')}"


def make_tools(get_canon: Callable[[], Canon], verdicts: Verdicts) -> list:
    """The tools, reading the canon fresh on each call through `get_canon`."""

    @tool("list_standards", "List the canon's standards and gotchas (kind gotcha = a mistake already "
          "made once): id, version, kind, the tags it applies to, title.", TAGS_SCHEMA)
    async def list_standards(args: dict[str, Any]) -> dict[str, Any]:
        canon = get_canon()
        tags = [t.strip() for t in str(args.get("tags") or "").split(",") if t.strip()]
        rows = canon.applicable(tags) if tags else canon.standards
        if not rows:
            return text_result("No standards apply to those tags." if tags else "The canon has no standards.")
        return text_result("\n".join(standard_line(s) for s in rows))

    @tool("read_standard", "Read one standard's full text by id.", ID_SCHEMA)
    async def read_standard(args: dict[str, Any]) -> dict[str, Any]:
        try:
            return text_result(get_canon().read_standard(str(args.get("id", ""))))
        except (KeyError, ValueError, OSError) as e:
            return error_result(str(e).strip("'\""))

    @tool("list_scaffolds", "List the canon's project scaffolds: id, version, status, menu path, tags.", NO_ARGS)
    async def list_scaffolds(args: dict[str, Any]) -> dict[str, Any]:
        rows = get_canon().scaffolds
        if not rows:
            return text_result("The canon has no scaffolds.")
        return text_result("\n".join(
            f"{s['id']} v{s.get('version', '?')} {s.get('status', '?')} [{' > '.join(map(str, s.get('path', [])))}] "
            f"tags={','.join(map(str, s.get('tags', [])))} {s.get('title', '')}" for s in rows))

    @tool("review_verdict", "Report your review of a draft: ok=true with no concerns approves it; "
          "otherwise ok=false and every concern. Call it exactly once per review.", VERDICT_SCHEMA)
    async def review_verdict(args: dict[str, Any]) -> dict[str, Any]:
        ok, concerns = args.get("ok"), args.get("concerns")
        if not isinstance(ok, bool) or not isinstance(concerns, list) or not all(isinstance(c, str) for c in concerns):
            return error_result("ok must be a boolean and concerns a list of strings")
        verdicts.calls.append((ok, [c.strip() for c in concerns if c.strip()]))
        return text_result("Verdict recorded.")

    return [list_standards, read_standard, list_scaffolds, review_verdict]

"""The knowledge base as Cortex tools: list and read standards, list scaffolds, and the review's
verdict. All of them only read or report, so none asks for approval. [[gotcha-approvals]]"""
from __future__ import annotations

from collections.abc import Callable
from dataclasses import dataclass, field
from typing import Any

from cortex_agent_sdk.cortexcode import tool

from .canonreader import Canon
from .cortex_session import error_result, text_result

SERVER = "kb"
PREFIX = f"mcp__{SERVER}__"
READ_ONLY = frozenset({"list_standards", "read_standard", "list_scaffolds", "review_verdict"})

TAGS_SCHEMA = {"type": "object", "properties": {"tags": {
    "type": "string", "description": "Comma-separated repo tags, e.g. 'python,cli'. Empty lists every standard."}}}
ID_SCHEMA = {"type": "object", "properties": {"id": {"type": "string"}}, "required": ["id"]}
NO_ARGS = {"type": "object", "properties": {}}
VERDICT_SCHEMA = {"type": "object", "properties": {
    "ok": {"type": "boolean", "description": "true only when you have no concerns"},
    "concerns": {"type": "array", "items": {"type": "string"},
                 "description": "One sentence each, saying what to change. Empty when ok."}},
    "required": ["ok", "concerns"]}


@dataclass
class Verdicts:
    """What review_verdict reported. The review gates /new on this data, never on prose.
    [[gotcha-agent-trust]]"""
    calls: list[tuple[bool, list[str]]] = field(default_factory=list)

    def clear(self) -> None:
        self.calls.clear()

    def approved(self) -> bool:
        return bool(self.calls) and all(ok for ok, concerns in self.calls)

    def concerns(self) -> list[str]:
        out = [c for _, concerns in self.calls for c in concerns]
        if not out and any(not ok for ok, _ in self.calls):
            out.append("The review did not approve the draft but named no concern.")
        return out


def standard_line(s: dict[str, Any]) -> str:
    applies = ", ".join(str(t) for t in s.get("applies_to", []))
    return f"{s['id']} v{s.get('version', '?')} ({s.get('kind', 'standard')}) [{applies}] {s.get('title', '')}"


